contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address accessControl, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        require(accessControl != address(0), "accessControl zero");

        c.initialize(accessControl); if (__ESBMC_reverted()) return;

        c.setLimits(maxMultiplier, minMultiplier, rate); if (__ESBMC_reverted()) return;

        assert(address(c).code.length > 0);
    }

    receive() external payable {}
}

