pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function _run(address accessControl, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) internal {
        vm.assume(accessControl != address(0));
        try c.initialize(accessControl) {} catch { return; }
        try c.setLimits(maxMultiplier, minMultiplier, rate) {} catch { return; }
        assertTrue(address(c).code.length > 0);
    }

    function testFuzz_run(address accessControl, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        vm.assume(accessControl.code.length == 0 && uint160(accessControl) > 0xffff && accessControl != address(this) && accessControl != address(c) && accessControl != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && accessControl != 0x000000000000000000636F6e736F6c652e6c6f67 && accessControl != 0x4e59b44847b379578588920cA78FbF26c0B4956C && accessControl != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(accessControl, maxMultiplier, minMultiplier, rate);
    }

    receive() external payable {}
}
